  function topNav(){return `<header class="topbar"><div class="topbrand"><img src="srs-vision-logo.png"><b>SRS VISION</b></div><nav class="topnav"><button data-nav="dashboard">⌂</button><button data-nav="projects">Projects</button><button data-nav="team">Teams</button><button data-nav="calendar">Calendar</button><button data-nav="reports">Reports</button></nav><div class="search"><span>⌕</span><input id="globalSearch" placeholder="Search projects, members, tools…"></div><div class="topactions"><button class="btn" data-nav="notifications">🔔</button><button class="status" data-nav="database" id="dbStatus"><span class="dot"></span><span><b>Local</b><small>Browser storage</small></span></button><div class="user"><span class="avatar">SV</span><div><b>SRS Vision</b><small>Team Workspace</small></div></div></div></header>`}
  function renderShell(){document.body.className='';$('#app').innerHTML=`<div class="app">${shellNav()}<main class="mainwrap">${topNav()}<div class="content" id="content"></div></main></div><nav class="mobileNav"><button data-nav="dashboard">⌂<br>Home</button><button data-nav="projects">▣<br>Projects</button><button data-nav="team">♧<br>Team</button><button data-nav="work">◉<br>Work</button><button data-nav="tools-hub">✦<br>Tools</button></nav>`;renderStatus();}
  function renderStatus(){const e=$('#dbStatus');if(!e)return;const cls=Live.status==='online'?'live':Live.status==='error'?'err':'dot';const label=Live.status==='online'?'Live Database':Live.status==='error'?'Local Mode':'Local';const sub=Live.status==='online'?'Realtime ON':Live.detail||'Auto-save enabled';e.innerHTML=`<span class="dot ${cls}"></span><span><b>${label}</b><small>${esc(sub)}</small></span>`}
