    <section class="kpis"><div class="kpi"><div class="kpiTop"><span>Total Projects</span><span>▣</span></div><b>${p.length}</b><span class="trend">↑ ${a} active</span><div class="hint">saved automatically</div></div><div class="kpi"><div class="kpiTop"><span>Team Members</span><span>♧</span></div><b>${state.team.members.length}</b><span class="trend">SRS Vision</span><div class="hint">single team</div></div><div class="kpi"><div class="kpiTop"><span>Active Work</span><span>✓</span></div><b>${state.tasks.filter(t=>t.status!=='Done').length}</b><span class="trend">${state.tasks.filter(t=>t.status==='Done').length} done</span><div class="hint">continue saved work</div></div><div class="kpi"><div class="kpiTop"><span>Profit / Loss</span><span>₹</span></div><b class="${profit>=0?'pos':'neg'}">${money(profit)}</b><span class="trend">Income ${money(income)}</span><div class="hint">Expense ${money(expense)}</div></div></section>
